<?php

declare(strict_types=1);

namespace Specrig\Tests;

use PHPUnit\Framework\TestCase;
use Specrig\Surface\Code;
use Specrig\Surface\Walker;
use Specrig\Tool\Service;

final class SurfaceTest extends TestCase
{
    public function testALaravelServiceServesItsRoutesAndCallsItsNeighbours(): void
    {
        $surface = (new Walker(new Service(__DIR__ . '/fixtures/laravel'), 'gateway'))->run();

        $this->assertSame(<<<'YAML'
            # Generated by `specrig surface` from the service's code.
            specrig: surface/1
            service: gateway
            publishes:
              - letters.sent
            consumes:
              - letters.*
            serves:
              - "* /hook"
              - GET /up
              - GET /v1/accounts/{id}
              - GET /v1/admin/letters
              - GET /v1/admin/notes
              - GET /v1/admin/notes/{note}
              - POST /v1/admin/letters
            calls:
              - DELETE /customers/{}
              - DELETE /sessions/{}
              - GET /customers/{}
              - GET /customers/{}/notes
              - POST /letters
            clients:
              App\Crm:
                - DELETE /customers/{}
                - GET /customers/{}
                - GET /customers/{}/notes
                - POST /letters
              App\Sessions:
                - DELETE /sessions/{}

            YAML, $surface->encode());
        $this->assertSame(<<<'YAML'
            # Generated by `specrig surface` from the service's code: what its boot is checked against.
            specrig: checks/1
            service: gateway
            optional:
              - CRM_TIMEOUT
              - CRM_URL
              - RABBIT_URL
            consumers:
              - App\Console\Commands\ConsumeLetters

            YAML, $surface->encodeChecks());
    }

    public function testASymfonyServiceServesItsAttributeRoutesUnderTheirImportAndReadsItsEnvironment(): void
    {
        $surface = (new Walker(new Service(__DIR__ . '/fixtures/symfony'), 'stock'))->run();

        $this->assertSame(<<<'YAML'
            # Generated by `specrig surface` from the service's code.
            specrig: surface/1
            service: stock
            publishes:
              - stock.reserved
            serves:
              - "* /api/health"
              - GET /api/orders/{id}
              - HEAD /ping
              - POST /api/orders
              - PUT /api/orders
            calls:
              - GET /stock/{}
              - PUT /stock/reserve
            clients:
              App\Warehouse:
                - GET /stock/{}
                - PUT /stock/reserve

            YAML, $surface->encode());
        $this->assertSame(<<<'YAML'
            # Generated by `specrig surface` from the service's code: what its boot is checked against.
            specrig: checks/1
            service: stock
            settings:
              - APP_SECRET
              - DATABASE_URL
              - RESERVE_LIMIT
              - WAREHOUSE_URL
            optional:
              - FEATURE_FLAG

            YAML, $surface->encodeChecks());
    }

    public function testAnEventNamedByDataIsRefusedAtTheLineThatNamesIt(): void
    {
        $dir = Temp::dir();
        file_put_contents("{$dir}/composer.json", '{"require": {"laravel/framework": "^13"}, "autoload": {"psr-4": {"App\\\\": "app/"}}}');
        mkdir("{$dir}/app");
        file_put_contents("{$dir}/app/Events.php", "<?php\nnamespace App;\nfinal class Events {\n    public function send(\$channel, string \$key) { \$channel->basic_publish(null, 'x', \"orders.{\$key}\"); }\n    public function placed(\$channel) { \$this->send(\$channel, strtolower('PLACED')); }\n}\n");

        $this->expectExceptionMessage("{$dir}/app/Events.php:4: publishes a name that is not a constant — it is a contract, give it one");
        (new Walker(new Service($dir), 'orders'))->run();
    }

    public function testARequestWhoseWholeAddressIsDataGoesOutside(): void
    {
        $this->assertSame('GET external', 'GET ' . Walker::path(Code::VARYING));
        $this->assertSame('/invoices/{}', Walker::path('https://billing.example.com/invoices/{}?page=2'));
        $this->assertSame('/', Walker::path('/'));
    }
}
